t.script:
(function(){
  function saveState(){
    var sw=[]; document.querySelectorAll('.trm-st').forEach(function(cb){ if(cb.checked){ sw.push(cb.value); } });
    var allCl=true, cw=[];
    document.querySelectorAll('.trm-cl').forEach(function(cb){ if(cb.checked){ cw.push(cb.value); } else { allCl=false; } });
    try{ localStorage.setItem('trmFilters', JSON.stringify({sw:sw, clAll:allCl, cw:cw})); }catch(e){}
  }
  function restoreState(){
    var raw=null; try{ raw=localStorage.getItem('trmFilters'); }catch(e){}
    if(!raw){ return; }
    var f; try{ f=JSON.parse(raw); }catch(e){ return; }
    if(f.sw){
      var sset={}; f.sw.forEach(function(x){ sset[x]=true; });
      document.querySelectorAll('.trm-st').forEach(function(cb){ cb.checked = !!sset[cb.value]; });
    }
    if(f.clAll === false){
      var cset={}; (f.cw||[]).forEach(function(x){ cset[x]=true; });
      document.querySelectorAll('.trm-cl').forEach(function(cb){ cb.checked = !!cset[cb.value]; });
    }
  }
  function applyFilter(){
    var st = {}; document.querySelectorAll('.trm-st').forEach(function(cb){ st[cb.value] = cb.checked; });
    var inStatus = {};
    document.querySelectorAll('.trm-task').forEach(function(c){
      if(st[c.getAttribute('data-status')]){ inStatus[c.getAttribute('data-client')] = true; }
    });
    document.querySelectorAll('.trm-cl-lbl').forEach(function(lbl){
      var cb = lbl.querySelector('.trm-cl');
      lbl.style.display = (cb && inStatus[cb.value]) ? '' : 'none';
    });
    var cl = {}; document.querySelectorAll('.trm-cl').forEach(function(cb){ cl[cb.value] = cb.checked; });
    document.querySelectorAll('.trm-task').forEach(function(c){
      var show = true;
      if(!st[c.getAttribute('data-status')]){ show = false; }
      if(!cl[c.getAttribute('data-client')]){ show = false; }
      c.style.display = show ? '' : 'none';
    });
    saveState();
    trmRenderCounts();
  }
  function trmRenderCounts(){
    var cl = {}; document.querySelectorAll('.trm-cl').forEach(function(cb){ cl[cb.value] = cb.checked; });
    var c = {facture:0,paye:0,brouillon:0,afacturer:0,annule:0,autre:0}, total=0;
    document.querySelectorAll('.trm-task').forEach(function(t){
      if(!cl[t.getAttribute('data-client')]){ return; }
      var s = t.getAttribute('data-status') || 'autre';
      if(c[s] === undefined){ s = 'autre'; }
      c[s]++; total++;
    });
    document.querySelectorAll('.trm-st-n').forEach(function(sp){
      var k = sp.getAttribute('data-st');
      sp.textContent = (c[k] === undefined ? 0 : c[k]);
    });
    var tot = document.getElementById('trmTotal'); if(tot){ tot.textContent = total; }
    document.querySelectorAll('.trm-st').forEach(function(cb){
      var lbl = cb.closest('.trm-st-lbl'); if(lbl){ lbl.classList.toggle('off', !cb.checked); }
    });
  }
  document.querySelectorAll('.trm-st').forEach(function(cb){ cb.addEventListener('change', applyFilter); });
  document.querySelectorAll('.trm-cl').forEach(function(cb){ cb.addEventListener('change', applyFilter); });
  var a=document.getElementById('clAll'); if(a){ a.addEventListener('click', function(){ document.querySelectorAll('.trm-cl').forEach(function(cb){cb.checked=true;}); applyFilter(); }); }
  var n=document.getElementById('clNone'); if(n){ n.addEventListener('click', function(){ document.querySelectorAll('.trm-cl').forEach(function(cb){cb.checked=false;}); applyFilter(); }); }
  var rf=document.getElementById('trmRefresh'); if(rf){ rf.addEventListener('click', function(){ location.reload(); }); }
  // ── Voile d'attente : bloque la page (et les autres boutons) pendant la génération des BC
  var trmBusy = false, trmTimer = null;
  function trmWaitOn(lbl){
    trmBusy = true;
    document.querySelectorAll('#trmSede,.trm-rec,#trmRefresh').forEach(function(x){ x.disabled = true; });
    var w = document.createElement('div'); w.id = 'trmWait';
    var card = document.createElement('div'); card.className = 'trm-wait-card';
    function el(cls, txt){ var e = document.createElement('div'); e.className = cls; if(txt){ e.textContent = txt; } card.appendChild(e); return e; }
    el('trm-spin');
    el('trm-wait-t', 'Génération des bons de commande « ' + lbl + ' »…');
    el('trm-wait-s', 'Odoo crée un BC confirmé par transport (≈ 2 à 3 s par bon). Un mois complet peut prendre plusieurs minutes.');
    el('trm-wait-w', '⚠ Ne recliquez pas et ne fermez pas la page.');
    var c = el('trm-wait-c', 'Temps écoulé : '); var cs = document.createElement('span'); cs.id = 'trmWaitC'; cs.textContent = '0'; c.appendChild(cs); c.appendChild(document.createTextNode(' s'));
    w.appendChild(card);
    document.body.appendChild(w);
    var t0 = Date.now();
    trmTimer = setInterval(function(){ var c = document.getElementById('trmWaitC'); if(c){ c.textContent = Math.round((Date.now() - t0) / 1000); } }, 1000);
    window.onbeforeunload = function(){ return 'Génération en cours — quitter la page ne l’interrompt pas mais vous perdrez le compte-rendu.'; };
  }
  function trmWaitOff(){
    trmBusy = false;
    if(trmTimer){ clearInterval(trmTimer); trmTimer = null; }
    window.onbeforeunload = null;
    var w = document.getElementById('trmWait'); if(w){ w.remove(); }
    document.querySelectorAll('#trmSede,.trm-rec,#trmRefresh').forEach(function(x){ x.disabled = false; });
  }
  function trmAlert(msg, reload){ setTimeout(function(){ alert(msg); if(reload){ location.reload(); } }, 80); }
  var TRM_RESEAU = 'Connexion coupée pendant le traitement (délai dépassé ou service redémarré).\n\nLes bons de commande déjà créés sont conservés : la page va s’actualiser, relancez ensuite le même bouton — les transports déjà pourvus d’un BC seront ignorés.';
  var sd=document.getElementById('trmSede'); if(sd){ sd.addEventListener('click', function(){
    if(trmBusy){ return; }
    var mp0 = document.getElementById('trmMonthPick');
    var m = (mp0 && mp0.value) || '';
    if(!/^\d{4}-\d{2}$/.test(m)){ alert('Mois affiché introuvable.'); return; }
    if(!confirm('Générer les bons de commande VEOLIA AGRICULTURE (LA SEDE) pour ' + m + ' ?\n\nPour chaque transport du mois SANS bon de commande : BC confirmé avec « Location Semi Fond-mouvant - par jours » (qté 1) + section Bon de pesée.\nTâches annulées et BC déjà existants ignorés.')){ return; }
    sd.disabled = true; sd.textContent = '… en cours'; trmWaitOn('SEDE');
    var y = parseInt(m.slice(0,4),10), mo = parseInt(m.slice(5,7),10);
    var fin = new Date(y, mo, 0).getDate();
    var au = m + '-' + ('0' + fin).slice(-2);
    fetch('https://ocr-pesee-webhook.onrender.com/heures/rpc', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({action_id:2078, ctx:{sede_du: m + '-01', sede_au: au}})})
    .then(function(r){ return r.json(); }).then(function(d){
      trmWaitOff(); sd.textContent = '⚡ SEDE';
      if(d.error){ trmAlert('Échec : ' + ((d.error.data && d.error.data.message) || d.error.message)); return; }
      var r = d.result || {};
      var msg = 'SEDE — ' + (r.faits || 0) + ' bon(s) de commande créé(s)';
      if(r.deja){ msg += '\n' + r.deja + ' tâche(s) avec BC déjà existant (ignorées)'; }
      if(r.annulees){ msg += '\n' + r.annulees + ' tâche(s) annulée(s) (ignorées)'; }
      if(r.sans_bon && r.sans_bon.length){ msg += '\n⚠ BC créés SANS bon de pesée (feuille vide) : ' + r.sans_bon.join(' · '); }
      trmAlert(msg, true);
    }).catch(function(){ trmWaitOff(); sd.textContent = '⚡ SEDE'; trmAlert(TRM_RESEAU, true); });
  }); }
  document.querySelectorAll('.trm-rec').forEach(function(b){ b.addEventListener('click', function(){
    if(trmBusy){ return; }
    var mp0 = document.getElementById('trmMonthPick');
    var m = (mp0 && mp0.value) || '';
    if(!/^\d{4}-\d{2}$/.test(m)){ alert('Mois affiché introuvable.'); return; }
    if(!confirm('Générer les bons de commande « ' + b.getAttribute('data-lbl') + ' » pour ' + m + ' ?\n\nPour chaque transport du mois SANS bon de commande : BC confirmé + articles de la recette + section Bon de pesée.\nTâches annulées et BC déjà existants ignorés.')){ return; }
    var old = b.textContent;
    b.disabled = true; b.textContent = '…'; trmWaitOn(b.getAttribute('data-lbl'));
    var y = parseInt(m.slice(0,4),10), mo = parseInt(m.slice(5,7),10);
    var au = m + '-' + ('0' + (new Date(y, mo, 0).getDate())).slice(-2);
    fetch('https://ocr-pesee-webhook.onrender.com/heures/rpc', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({action_id:2081, ctx:{tb_recette: b.getAttribute('data-rec'), tb_du: m + '-01', tb_au: au}})})
    .then(function(r){ return r.json(); }).then(function(d){
      trmWaitOff(); b.textContent = old;
      if(d.error){ trmAlert('Échec : ' + ((d.error.data && d.error.data.message) || d.error.message)); return; }
      var r = d.result || {};
      var msg = b.getAttribute('data-lbl') + ' — ' + (r.faits || 0) + ' bon(s) de commande créé(s)';
      if(r.deja){ msg += '\n' + r.deja + ' tâche(s) avec BC déjà existant (ignorées)'; }
      if(r.annulees){ msg += '\n' + r.annulees + ' tâche(s) annulée(s) (ignorées)'; }
      if(r.futurs){ msg += '\n' + r.futurs + ' transport(s) à venir (ignorés — pas encore de bon de pesée)'; }
      if(r.non_faits){ msg += '\n' + r.non_faits + ' tâche(s) pas à l\u2019état « Fait » (ignorées)'; }
      if(r.sans_bon && r.sans_bon.length){ msg += '\n⚠ BC créés SANS bon de pesée (feuille vide) : ' + r.sans_bon.join(' · '); }
      if(r.a_verifier && r.a_verifier.length){ msg += '\n⚠ À vérifier : ' + r.a_verifier.join(' · '); }
      trmAlert(msg, true);
    }).catch(function(){ trmWaitOff(); b.textContent = old; trmAlert(TRM_RESEAU, true); });
  }); });
  var mp=document.getElementById('trmMonthPick'); if(mp){ mp.addEventListener('change', function(){
    if(!/^\d{4}-\d{2}$/.test(mp.value || '')){ return; }
    var url = new URL(window.location);
    url.searchParams.set('month', mp.value);
    window.location.href = url.toString();
  }); }
  restoreState();
  applyFilter();
})();
